function driverOnboardingFields(){return `<section class="driver-onboarding-fields"><h3>Driver & vehicle onboarding</h3><p>Submit your driving licence, vehicle, documents, weekly availability, and mobile-money details. Dispatch starts after manager verification.</p><div class="form-grid"><div class="field"><label>Terminal</label><select id=driverStation class=form-select required></select></div><div class="field"><label>Licence number</label><input id=driverLicence class=form-control required></div><div class="field"><label>Vehicle registration</label><input id=driverReg class=form-control required></div><div class="field"><label>Vehicle type</label><input id=driverType class=form-control placeholder="Minibus, van…" required></div><div class="field"><label>Passenger capacity</label><input id=driverCapacity type=number min=1 max=60 class=form-control required></div><div class="field"><label>Mobile-money network</label><select id=driverPartner class=form-select required></select></div><div class="field"><label>Mobile-money payout number</label><input id=driverPayoutPhone class=form-control required></div><div class="field"><label>Preferred payout timing</label><select id=driverPayoutGate class=form-select required><option value=manager_completion>After trip completion and manager confirms riders</option><option value=onboard>As each rider confirms onboard</option></select><small class=field-help>A station manager can override this choice.</small></div><fieldset class="field"><legend>Weekly availability</legend><div class="days-picker">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<label class="day-option"><input class=driver-day type=checkbox value=${i}><span>${d}</span></label>`).join('')}</div></fieldset><div class="form-grid"><div class="field"><label>Available from</label><input id=driverFrom type=time class=form-control value=05:00 required></div><div class="field"><label>Available until</label><input id=driverUntil type=time class=form-control value=20:00 required></div></div><div class="field"><label>Driving licence document</label><input id=driverLicenceFile type=file accept=".pdf,.jpg,.jpeg,.png" class=form-control required><input id=driverLicenceExpiry type=date class=form-control aria-label="Licence expiry date" required></div><div class="field"><label>Vehicle registration document</label><input id=driverRegFile type=file accept=".pdf,.jpg,.jpeg,.png" class=form-control required></div><div class="field"><label>Insurance document</label><input id=driverInsuranceFile type=file accept=".pdf,.jpg,.jpeg,.png" class=form-control required><input id=driverInsuranceExpiry type=date class=form-control aria-label="Insurance expiry date" required></div></div></section>`}
let registrationOptions;
let invitationToken='',invitationDetails=null,inviteOtpReady=false,inviteApplicantStatus=null;
function invitedDriverFields(){return `<section id="inviteDriverFields" class="driver-onboarding-fields"><h3>Driver & vehicle application</h3><p>Your invitation fixes your tenant, station, and organization. Dispatch is enabled only after document verification.</p><div class="form-grid"><div class="field"><label for=driverLicence>Licence number</label><input id=driverLicence class=form-control required></div><div class="field"><label for=driverReg>Vehicle registration</label><input id=driverReg class=form-control required></div><div class="field"><label for=driverType>Vehicle type</label><input id=driverType class=form-control required></div><div class="field"><label for=driverCapacity>Passenger capacity</label><input id=driverCapacity type=number min=1 max=60 class=form-control required></div><div class="field"><label for=driverPartner>Mobile-money network</label><select id=driverPartner class=form-select required></select></div><div class="field"><label for=driverPayoutPhone>Mobile-money payout number</label><input id=driverPayoutPhone class=form-control required></div><div class="field"><label for=driverPayoutGate>Preferred payout timing</label><select id=driverPayoutGate class=form-select required><option value=manager_completion>After trip completion and manager confirms riders</option><option value=onboard>As each rider confirms onboard</option></select></div><fieldset class="field"><legend>Weekly availability</legend><div class="days-picker">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((day,index)=>`<label class="day-option"><input class=driver-day type=checkbox value=${index}><span>${day}</span></label>`).join('')}</div></fieldset><div class="field"><label for=driverFrom>Available from</label><input id=driverFrom type=time class=form-control value=05:00 required></div><div class="field"><label for=driverUntil>Available until</label><input id=driverUntil type=time class=form-control value=20:00 required></div><div class="field"><label for=driverLicenceFile>Driving licence document</label><input id=driverLicenceFile type=file accept=".pdf,.jpg,.jpeg,.png" class=form-control required><input id=driverLicenceExpiry type=date class=form-control aria-label="Licence expiry date" required></div><div class="field"><label for=driverRegFile>Vehicle registration document</label><input id=driverRegFile type=file accept=".pdf,.jpg,.jpeg,.png" class=form-control required></div><div class="field"><label for=driverInsuranceFile>Insurance document</label><input id=driverInsuranceFile type=file accept=".pdf,.jpg,.jpeg,.png" class=form-control required><input id=driverInsuranceExpiry type=date class=form-control aria-label="Insurance expiry date" required></div></div></section>`}
async function showOnboardingInvite(){invitationToken=new URLSearchParams(location.search).get('invite')||'';if(!invitationToken)return showLanding();try{const response=await fetch('/api/v1/onboarding/invitations/'+encodeURIComponent(invitationToken));const details=await response.json();if(!response.ok)throw Error(details.error||'This invitation is unavailable.');invitationDetails=details;renderOnboardingInvite()}catch(error){$('hd').classList.remove('active');$('app').classList.add('auth-view');$('app').innerHTML=`<div class="station-desk"><h1 class="station-title">Invitation unavailable</h1><p class="station-sub">${escapeHtml(error.message||'This invitation is expired or has been revoked.')}</p><button class="btn btn-outline-secondary" type="button" data-click="choose-role">Continue to sign in</button></div>`}}
function renderOnboardingInvite(){const driver=invitationDetails.role==='driver';inviteOtpReady=false;inviteApplicantStatus=null;$('hd').classList.remove('active');$('app').classList.add('auth-view');$('app').innerHTML=`<div class="station-desk"><h1 class="station-title">${driver?'Driver':'Porter'} application</h1><p class="station-sub">Invitation for ${escapeHtml(invitationDetails.station)}, ${escapeHtml(invitationDetails.tenant)}${invitationDetails.organization?` · ${escapeHtml(invitationDetails.organization)}`:''}. Scope is locked by the tenant administrator.</p><div class="auth-shell"><div class="auth-card"><div class="auth-form"><div class="field"><label for=inviteName>Full name</label><input id=inviteName class=form-control autocomplete=name required></div><div class="field"><label for=invitePhone>Phone</label><input id=invitePhone class=form-control autocomplete=tel required></div>${driver?invitedDriverFields():''}<label class="small mb-0 d-block"><input type=checkbox id=inviteConsent> I accept the <a href="/terms.html" target="_blank">Terms & Privacy Notice</a> (required)</label><div class="portal-form-actions">${btn('Send verification code',()=>requestInviteOtp(),'primary')}</div><div id=inviteOtpBox class="otp-box"><div class="field"><label for=inviteCode>OTP code</label><input id=inviteCode class=form-control inputmode=numeric autocomplete=one-time-code></div>${invitationDetails.applicationExists?btn('Check application status',()=>checkInviteStatus(),'secondary'):''}${btn('Submit application',()=>submitInviteApplication(),'success')}</div><div id=inviteStatus class="small mt-3" role=status aria-live=polite></div><div id=inviteFinalAction></div></div></div></div></div>`;if(driver)loadRegistrationOptions();if(invitationDetails.applicationExists){$('inviteDriverFields')?.setAttribute('hidden','');$('inviteConsent')?.closest('label')?.setAttribute('hidden','');$('inviteOtpBox')?.classList.remove('visible');$('inviteStatus').textContent='Enter the phone number used for this application, then request a code to view its status or resubmit.'}}
async function requestInviteOtp(){const phone=sanitizePhone(v('invitePhone'));if(!phone)return showToast('Enter a valid phone number.','error');const result=await authRequest(`/onboarding/invitations/${encodeURIComponent(invitationToken)}/request-otp`,{phone});if(!result)return;inviteOtpReady=true;$('inviteOtpBox').classList.add('visible');$('inviteStatus').textContent='A verification code was sent to your phone.';showToast('Verification code sent.','success')}
async function checkInviteStatus(){const phone=sanitizePhone(v('invitePhone')),code=sanitizeOTP(v('inviteCode'));if(!phone||!code)return showToast('Enter your phone number and verification code.','error');const result=await authRequest(`/onboarding/invitations/${encodeURIComponent(invitationToken)}/status`,{phone,code});if(!result)return;inviteOtpReady=false;inviteApplicantStatus=result.status;$('inviteCode').value='';const history=result.history.map(item=>`<li><strong>${escapeHtml(item.status.replace('_',' '))}</strong> · ${escapeHtml(item.created_at)}${item.comment?`<p>${escapeHtml(item.comment)}</p>`:''}</li>`).join('');$('inviteStatus').innerHTML=`<strong>Application status: ${escapeHtml(result.status.replace('_',' '))}</strong>${result.comment?`<p>${escapeHtml(result.comment)}</p>`:''}${history?`<details><summary>Review history</summary><ol>${history}</ol></details>`:''}`;const needsChanges=result.status==='needs_changes';$('inviteDriverFields')?.toggleAttribute('hidden',!needsChanges);$('inviteConsent')?.closest('label')?.toggleAttribute('hidden',!needsChanges);if(needsChanges)$('inviteStatus').insertAdjacentHTML('beforeend','<p>Update the requested information and upload documents again, then request a new code before resubmitting.</p>');if(result.status==='approved')$('inviteFinalAction').innerHTML='<button class="btn btn-primary" type="button" data-click="invite-portal">Continue to sign in and set your PIN</button>';if(result.status==='rejected')$('inviteFinalAction').textContent='This decision is final; this invitation cannot be resubmitted.'}
async function collectInvitedDriverApplication(){for(const id of ['driverLicence','driverReg','driverType','driverCapacity','driverPartner','driverPayoutPhone','driverPayoutGate','driverFrom','driverUntil','driverLicenceFile','driverLicenceExpiry','driverRegFile','driverInsuranceFile','driverInsuranceExpiry']){const field=$(id);if(!field?.checkValidity()){field?.reportValidity();throw Error('Complete all required driver application fields before submitting.')}}if(!sanitizePhone(v('driverPayoutPhone')))throw Error('Enter a valid mobile-money payout number.');if(v('driverFrom')>=v('driverUntil'))throw Error('Available-until time must be later than available-from time.');const today=new Date().toISOString().slice(0,10);if(v('driverLicenceExpiry')<=today||v('driverInsuranceExpiry')<=today)throw Error('Licence and insurance expiry dates must be in the future.');const days=[...document.querySelectorAll('.driver-day:checked')].map(input=>+input.value);if(!days.length)throw Error('Choose at least one availability day.');const fileIds=['driverLicenceFile','driverRegFile','driverInsuranceFile'],files=fileIds.map(id=>$(id).files[0]);if(files.some(file=>file.size>3e6)||files.reduce((sum,file)=>sum+file.size,0)>8e6)throw Error('Each document must be under 3MB and all documents together under 8MB.');const documents={licence:await readOnboardingFile('driverLicenceFile'),vehicle_registration:await readOnboardingFile('driverRegFile'),insurance:await readOnboardingFile('driverInsuranceFile')};documents.licence.expiresOn=v('driverLicenceExpiry');documents.insurance.expiresOn=v('driverInsuranceExpiry');return{licence:v('driverLicence'),reg:v('driverReg'),type:v('driverType'),capacity:+v('driverCapacity'),payoutPartner:v('driverPartner'),payoutPhone:v('driverPayoutPhone'),payoutGate:v('driverPayoutGate'),days,startTime:v('driverFrom'),endTime:v('driverUntil'),documents}}
async function submitInviteApplication(){const phone=sanitizePhone(v('invitePhone')),name=sanitizeText(v('inviteName'),100),code=sanitizeOTP(v('inviteCode'));if(!phone||!name||!code)return showToast('Enter your name, phone number, and verification code.','error');if(!inviteOtpReady)return showToast('Request a new verification code before submitting.','error');if(!$('inviteConsent').checked)return showToast('Accept the Terms and Privacy Notice before submitting.','error');try{const form=invitationDetails.role==='driver'?await collectInvitedDriverApplication():{};const result=await authRequest(`/onboarding/invitations/${encodeURIComponent(invitationToken)}/submit`,{phone,name,code,consent:true,...form});if(!result)return;inviteOtpReady=false;invitationDetails.applicationExists=true;$('inviteDriverFields')?.setAttribute('hidden','');$('inviteConsent')?.closest('label')?.setAttribute('hidden','');$('inviteCode').value='';$('inviteStatus').textContent='Application submitted. Status: Pending review. Reopen this invitation and verify your phone to view comments or resubmit if changes are requested.';showToast('Application submitted for tenant review.','success')}catch(error){showFailure(error)}}
