const feeKeys=['station_fee_pct','platform_fee_pct','driver_station_fee_pct','driver_platform_fee_pct','loading_fee_pct','driver_loading_fee_pct'],tenantFeeKeys=feeKeys.slice(0,4),organizationFeeKeys=feeKeys.slice(4),feeLabels=['Rider station charge (%)','Rider platform charge (%)','Driver station deduction (%)','Driver platform deduction (%)','Rider loading charge (%)','Driver loading deduction (%)'];let feeSettings;
