let feeShareRows=[],feeShareEndpoint='/admin/fee-shares',feeShareFixedScope='';
function currentFeeShares(scope,kind,stream){const[type,id='0']=scope.split(':'),match=(row,scopeType,scopeId)=>row.scope_type===scopeType&&row.scope_id===Number(scopeId)&&row.fee_kind===kind&&row.stream===stream;let rows=feeShareRows.filter(row=>match(row,type,id));if(!rows.length&&type!=='global')rows=feeShareRows.filter(row=>match(row,'global',0));const shares={rider:0,driver:0,organization:0,tenant:0};for(const row of rows)shares[row.payer_type]=row.percentage;if(!rows.length)shares[stream]=100;return shares}
function syncFeeShareEditor(){const kind=$('fee-share-kind')?.value,scope=$('fee-share-scope')?.value,stream=$('fee-share-stream')?.value;if(!kind||!scope||!stream)return;const scopeSelect=$('fee-share-scope');if(!feeShareFixedScope){for(const option of scopeSelect.options){const allowed=kind==='platform'?option.value==='global':kind==='station'?option.value==='global'||option.value.startsWith('tenant:'):option.value==='global'||option.value.startsWith('organization:');option.hidden=!allowed}if(scopeSelect.selectedOptions[0]?.hidden)scopeSelect.value='global'}const values=currentFeeShares(scopeSelect.value,kind,stream);for(const payer of ['rider','driver','organization','tenant']){const field=$(`fee-share-${payer}`);if(field)field.value=values[payer]}}
function feeShareEditor(rows,scopes,kinds,endpoint,fixedScope=''){feeShareRows=rows;feeShareEndpoint=endpoint;feeShareFixedScope=fixedScope;const scopeOptions=scopes.map(s=>`<option value="${escapeHtml(s.value)}">${escapeHtml(s.label)}</option>`).join(''),kindOptions=kinds.map(k=>`<option value="${k}">${k==='station'?'Station fee':k==='platform'?'Platform fee':'Loading fee'}</option>`).join(''),fixed=fixedScope?`<input id="fee-share-scope" type="hidden" value="${escapeHtml(fixedScope)}">`: `<div class="form-field"><label class="field-label" for="fee-share-scope">Setup scope</label><select id="fee-share-scope" class="form-select">${scopeOptions}</select></div>`;const fields=['rider','driver','organization','tenant'].map(p=>`<div class="form-field"><label class="field-label" for="fee-share-${p}">${p[0].toUpperCase()+p.slice(1)} share (%)</label><input id="fee-share-${p}" type=number min=0 max=100 step=1 class=form-control value=0></div>`).join('');setTimeout(syncFeeShareEditor,0);return card('Fee payer shares',`<p class="panel-intro">Choose how each fee is funded. The payer shares must total 100%. The configured split is recorded against each new booking and used for settlement balances.</p><div class="portal-form-grid">${fixed}<div class="form-field"><label class="field-label" for="fee-share-kind">Fee type</label><select id="fee-share-kind" class="form-select">${kindOptions}</select></div><div class="form-field"><label class="field-label" for="fee-share-stream">Charge stream</label><select id="fee-share-stream" class="form-select"><option value="rider">Rider charge</option><option value="driver">Driver deduction</option></select></div>${fields}</div><div class="portal-form-actions">${btn('Save payer shares',()=>saveFeeShareConfig(),'success')}</div>`,'portal-card')}
