function accountingReportMarkup(report){const totals=report.periodAccounts.map(row=>({...row,debits:formatPesewas(row.debits_pesewas),credits:formatPesewas(row.credits_pesewas),amount:formatPesewas(row.amount_pesewas)})),balances=report.accounts.map(row=>({...row,debits:formatPesewas(row.debits_pesewas),credits:formatPesewas(row.credits_pesewas),balance:formatPesewas(row.balance_pesewas)})),journal=report.journal.slice(0,50).map(row=>({...row,debit:formatPesewas(row.debit_pesewas),credit:formatPesewas(row.credit_pesewas)})),issues=report.reconciliation.unposted.map(row=>({...row,amount:formatPesewas(row.amount_pesewas)}));return `<div class="portal-metrics"><article class="portal-stat"><span>Income</span><strong>${formatPesewas(report.income_pesewas)}</strong></article><article class="portal-stat"><span>Expenses</span><strong>${formatPesewas(report.expenses_pesewas)}</strong></article><article class="portal-stat"><span>Net</span><strong>${formatPesewas(report.net_pesewas)}</strong></article></div><h3 class="section-subtitle">Reconciliation</h3><p>${report.reconciliation.unposted_count} source event(s) awaiting journal posting · ${report.reconciliation.unbalanced_transactions} unbalanced transaction(s) · unallocated receipts ${formatPesewas(report.reconciliation.unallocated_receipts_pesewas)}.</p>${issues.length?tbl(issues,['source_type','source_id','reference','amount','effective_at']):'<p class="small text-muted">All eligible source events are posted and balanced.</p>'}<h3 class="section-subtitle">Income and expenses · period</h3>${tbl(totals,['code','name','account_type','debits','credits','amount'])}<h3 class="section-subtitle">Account balances · through period end</h3>${tbl(balances,['code','name','account_type','debits','credits','balance'])}<h3 class="section-subtitle">Journal · latest 50 lines</h3>${tbl(journal,['effective_at','source_type','memo','account','debit','credit'],row=>row.source_type=='manual_expense'&&row.account_code=='6200'?btn('Reverse expense',()=>reverseAccountingExpense(row),'warning'):'')}`}
async function loadAccountingReports(){const target=$('accounting-results');if(!target)return;try{const report=await api('/accounting/report?'+accountingParams().toString());target.innerHTML=accountingReportMarkup(report)}catch(error){showFailure(error)}}
async function exportAccountingReport(name){try{const response=await fetch(`/api/v1/reports/${name}?${accountingParams().toString()}&format=csv`,{credentials:'same-origin'});if(!response.ok){let message='Accounting export failed.';try{message=(await response.json()).error||message}catch{}throw Error(message)}const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download=`${name}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(error){showFailure(error)}}
