async function accountingCard(tenants,permissions){const today=new Date().toISOString().slice(0,10),from=new Date(Date.now()-29*864e5).toISOString().slice(0,10),tenantOptions=U.role=='admin'?`<option value="">All books</option>${tenants.map(item=>`<option value="${item.id}">${escapeHtml(item.name)}</option>`).join('')}`:'',expenseForm=U.role=='admin'||permissions?.['accounting.expense']?`<div class="section-divider"></div><h3 class="section-subtitle">Record operating expense</h3><p class="small text-muted">Expense entries are immutable and append-only. Verify details before posting; posted expenses can be reversed from the journal.</p><div class="portal-form-grid"><div class="form-field"><label class="field-label" for="accounting-expense-date">Date</label><input id="accounting-expense-date" type=date class=form-control value="${today}"></div><div class="form-field"><label class="field-label" for="accounting-expense-category">Category</label><input id="accounting-expense-category" maxlength=80 class=form-control placeholder="Fuel, maintenance, rent"></div><div class="form-field"><label class="field-label" for="accounting-expense-amount">Amount (GHS)</label><input id="accounting-expense-amount" type=number min=0.01 step=0.01 class=form-control></div><div class="form-field"><label class="field-label" for="accounting-expense-reference">Reference (optional)</label><input id="accounting-expense-reference" maxlength=100 class=form-control></div><div class="form-field"><label class="field-label" for="accounting-expense-description">Description</label><input id="accounting-expense-description" maxlength=240 class=form-control></div></div><div class="portal-form-actions">${btn('Post expense',()=>recordAccountingExpense(),'success')}</div>`:'',html=card('Accounting ledger',`<p class="panel-intro">Double-entry GHS ledger. Passenger fares are recorded as driver payables; allocated fees are income for their recipients. Revenue/expense reports reflect posted activity only.</p><div class="portal-form-grid"><div class="form-field"><label class="field-label" for="accounting-from">From</label><input id="accounting-from" type=date class=form-control value="${from}"></div><div class="form-field"><label class="field-label" for="accounting-to">To</label><input id="accounting-to" type=date class=form-control value="${today}"></div>${U.role=='admin'?`<div class="form-field"><label class="field-label" for="accounting-tenant">Book view</label><select id="accounting-tenant" class=form-select>${tenantOptions}</select></div>`:''}</div><div class="portal-form-actions">${btn('Refresh ledger',()=>loadAccountingReports(),'primary')}${btn('Export journal CSV',()=>exportAccountingReport('accounting-journal'),'outline-secondary')}${btn('Export income/expense CSV',()=>exportAccountingReport('accounting-income-expenses'),'outline-secondary')}${btn('Export reconciliation CSV',()=>exportAccountingReport('accounting-reconciliation'),'outline-secondary')}</div><div id="accounting-results"><p class="small text-muted">Loading accounting reports...</p></div>${expenseForm}`,'portal-card');setTimeout(loadAccountingReports,0);return html}
