async function payDriverFees(){const data=await api('/drivers/me/fees');if(!data.outstanding_pesewas)return showToast('No fees are currently owed.','info');const values=await openAppDialog({title:'Pay fees with MoMo',message:`Outstanding balance GHS ${(data.outstanding_pesewas/100).toFixed(2)}. The payment will be allocated to the oldest items first.`,fields:[{name:'amountGhs',label:'Amount (GHS)',type:'number',min:0.01,max:data.outstanding_pesewas/100,step:0.01,required:true}],confirmLabel:'Request payment'});if(values)return act('/drivers/me/fees/pay',{amountGhs:values.amountGhs})}
async function checkDriverFeeStatus(transactionId){try{const result=await api('/drivers/me/fees/status','POST',{transactionId});showToast(`Fee payment status: ${result.status}`,result.status==='Succeeded'?'success':'info')}catch(e){showFailure(e)}finally{refreshAfterMutation()}}
