const afq=csv=>'/manager/audit?limit=15&page='+AF.page+['action','entity','from','to'].map(k=>AF[k]?'&'+k+'='+encodeURIComponent(AF[k]):'').join('')+(csv?'&format=csv':'');
async function audit(){const el=$('aud');if(!el)return;const r=await fetch('/api/v1'+afq(),{credentials:'same-origin'}),rows=await r.json(),tot=+r.headers.get('X-Total-Count');el.innerHTML=tbl(rows,['at','actor_name','action','entity','eid','meta'])+`<div class=small>Page ${AF.page} of ${Math.max(1,Math.ceil(tot/15))} (${tot} records)</div>`+btn('Prev',()=>afp(-1),'secondary')+btn('Next',()=>afp(1),'secondary')+btn('Export CSV',()=>afx(),'outline-secondary')}
const afp=d=>{AF.page=Math.max(1,AF.page+d);return audit()},afs=(k,x)=>{AF[k]=x;AF.page=1};
