const bars=(t,rows)=>{const m=Math.max(1,...rows.map(r=>r[1]));return `<h6 class=mt-3>${escapeHtml(t)}</h6>`+(rows.map(r=>`<div class="d-flex align-items-center small mb-1"><div class="chart-label text-truncate">${escapeHtml(r[0])}</div><progress class="chart-bar" max="50" value="${Math.round(r[1]/m*50)}"></progress><span class=ms-2>${escapeHtml(r[1])}</span></div>`).join('')||'<div class="text-muted small">No data</div>')};
const sumBy=(rows,k,x)=>{const m={};rows.forEach(r=>m[r[k]]=(m[r[k]]||0)+(+r[x]||0));return Object.entries(m)};
async function charts(){const qs='?from='+(RF||'0000-01-01')+'&to='+(RT||'9999-12-31'),rd=await api('/reports/route-demand'+qs),du=await api('/reports/driver-utilisation'+qs),tot=k=>rd.reduce((s,r)=>s+(+r[k]||0),0);
 CH=bars('Seats requested by route',sumBy(rd,'route','seats'))+bars('Seats requested per day',sumBy(rd,'date','seats').sort())+bars('Busiest hours (seats)',sumBy(rd,'hour','seats').sort())+bars('Outcomes (bookings)',[['Completed',tot('completed')],['Cancelled',tot('cancelled')],['No-shows',tot('no_shows')],['Still waiting',tot('waiting')]])+bars('Seats carried by driver',du.map(r=>[r.driver+' '+r.reg,r.seats_carried]))+bars('Trips by driver',du.map(r=>[r.driver+' '+r.reg,r.trips]));$('ch').innerHTML=CH}
