let es,liveConnecting=false,liveFailures=0,liveRetryTimer=0,liveFallbackTimer=0,livePollingFallback=false,liveRefreshTimer=0,liveRefreshPending=false;
function scheduleLiveRefresh(){liveRefreshPending=true;clearTimeout(liveRefreshTimer);liveRefreshTimer=setTimeout(()=>{liveRefreshTimer=0;if(!T||document.activeElement.matches('input,select'))return;liveRefreshPending=false;load()},400)}
document.addEventListener('focusout',()=>{if(liveRefreshPending)scheduleLiveRefresh()});
function retryLiveUpdates(){if(!T)return;liveFailures++;if(liveFailures>=3){livePollingFallback=true;liveFallbackTimer=setTimeout(()=>{liveFallbackTimer=0;livePollingFallback=false;liveFailures=0;live()},300000);return}liveRetryTimer=setTimeout(()=>{liveRetryTimer=0;live()},Math.min(30000,5000*2**(liveFailures-1))+Math.random()*1000)}
async function live(){if(es||liveConnecting||!T||livePollingFallback||typeof EventSource==='undefined')return;liveConnecting=true;try{const t=await api('/events/ticket','POST');if(!T||livePollingFallback)return;const source=new EventSource('/api/v1/events?ticket='+encodeURIComponent(t.ticket));es=source;source.addEventListener('open',()=>{liveFailures=0;setNetworkIssue(false);clearTimeout(liveFallbackTimer);liveFallbackTimer=0});source.addEventListener('notify',scheduleLiveRefresh);source.addEventListener('refresh',scheduleLiveRefresh);source.onerror=()=>{if(es!==source)return;source.close();es=null;retryLiveUpdates()}}catch(e){showFailure(e,'Could not connect live updates.');retryLiveUpdates()}finally{liveConnecting=false}}
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js');
addEventListener('offline',()=>setNetworkIssue(true));addEventListener('online',()=>{if(T)load();else fetch('/healthz',{cache:'no-store'}).then(response=>setNetworkIssue(!response.ok)).catch(()=>setNetworkIssue(true))});if(!navigator.onLine)setNetworkIssue(true);
if(T){if(sessionExpiresAt)scheduleSessionExpiry();scheduleSessionIdleTimeout()}load();setInterval(()=>{if(T&&!es&&!document.activeElement.matches('input,select'))load()},60000);
